import{_ as t,o as a,c as i,a2 as e}from"./chunks/framework.CsGzzEsd.js";const b=JSON.parse('{"title":"JLPT N2 計画","description":"","frontmatter":{"title":"JLPT N2 計画"},"headers":[],"relativePath":"jp/blogs/JLPT-N2/plan.md","filePath":"jp/blogs/JLPT-N2/plan.md"}'),r={name:"jp/blogs/JLPT-N2/plan.md"};function d(o,l,h,n,s,u){return a(),i("div",null,[...l[0]||(l[0]=[e('<h1 id="jlpt-n2-学習計画" tabindex="-1">JLPT N2 学習計画 <a class="header-anchor" href="#jlpt-n2-学習計画" aria-label="Permalink to &quot;JLPT N2 学習計画&quot;">​</a></h1><blockquote><p><strong>前提：</strong> 準備期間は 24 週間、1 週あたり約 <strong>7 時間</strong>。試験対策と実際に使える日本語の両方を目指すので、読解と聴解は常に本物の素材とつなげておく。</p></blockquote><h2 id="完了の定義" tabindex="-1">完了の定義 <a class="header-anchor" href="#完了の定義" aria-label="Permalink to &quot;完了の定義&quot;">​</a></h2><ul><li>N2 の基本語彙と漢字を、単語カードの上だけでなく文脈の中で認識できる。</li><li>N2 レベルの長さの文章を、明確な目的・構成の把握・コントロールされたペースで読める。</li><li>一度聞くだけで、主張・立場・重要な詳細を追える。</li><li>時間を計った模擬試験 3 回すべてで、各区分と総合の合格点を余裕をもって上回る。</li></ul><h2 id="週のリズム" tabindex="-1">週のリズム <a class="header-anchor" href="#週のリズム" aria-label="Permalink to &quot;週のリズム&quot;">​</a></h2><table tabindex="0"><thead><tr><th>頻度</th><th style="text-align:right;">時間</th><th>内容</th></tr></thead><tbody><tr><td>毎日</td><td style="text-align:right;">20 分</td><td>間隔反復：語彙、漢字、例文を 1 つ音読。</td></tr><tr><td>週 3 回</td><td style="text-align:right;">35 分</td><td>文法パターン → 似たパターンとの対比 → 8–12 問。</td></tr><tr><td>週 3 回</td><td style="text-align:right;">30 分</td><td>能動的な聴解：予測し、1 回聞き、要約してからスクリプトで確認。</td></tr><tr><td>週 2 回</td><td style="text-align:right;">45 分</td><td>時間を計った読解のあと、構成とミスを分析。</td></tr><tr><td>週末</td><td style="text-align:right;">90 分</td><td>区分ミックス演習と週次の振り返り。</td></tr></tbody></table><h2 id="_24-週間のロードマップ" tabindex="-1">24 週間のロードマップ <a class="header-anchor" href="#_24-週間のロードマップ" aria-label="Permalink to &quot;24 週間のロードマップ&quot;">​</a></h2><h3 id="フェーズ-1-—-現状把握と仕組みづくり-第-1–2-週" tabindex="-1">フェーズ 1 — 現状把握と仕組みづくり（第 1–2 週） <a class="header-anchor" href="#フェーズ-1-—-現状把握と仕組みづくり-第-1–2-週" aria-label="Permalink to &quot;フェーズ 1 — 現状把握と仕組みづくり（第 1–2 週）&quot;">​</a></h3><ul><li>言語知識・読解・聴解をカバーするサンプル問題を、時間を計って解く。</li><li>ミスを分類する：語彙、文法のニュアンス、文のつながり、読む速さ、聞き逃した手がかり、注意力。</li><li>各スキルにつきメインの講座か本を 1 つだけ選ぶ。ほかの教材は「待ちリスト」へ。</li><li>例文ベースの復習デッキを始める。新規カードは、復習が 25 分以内に収まる量に抑える。</li></ul><h3 id="フェーズ-2-—-網羅-第-3–12-週" tabindex="-1">フェーズ 2 — 網羅（第 3–12 週） <a class="header-anchor" href="#フェーズ-2-—-網羅-第-3–12-週" aria-label="Permalink to &quot;フェーズ 2 — 網羅（第 3–12 週）&quot;">​</a></h3><ul><li>1 日に語彙 12–15 語と漢字 4–6 字を、週 6 日学ぶ。</li><li>週に 8–10 の文法パターンを、原因・譲歩・限定・傾向などの対比グループで学ぶ。</li><li>毎日短い生の文章を 1 本読む：NHK のニュース、エッセイ、商品ページ、職場のお知らせなど。</li><li>毎日 15–20 分日本語を聞く。そのうち 3 日はスクリプトを使って精聴する。</li></ul><p>毎週日曜日に、その週の文法パターンを 2 つ使って 150–250 字の要約を書く。</p><h3 id="フェーズ-3-—-スピードと統合-第-13–18-週" tabindex="-1">フェーズ 3 — スピードと統合（第 13–18 週） <a class="header-anchor" href="#フェーズ-3-—-スピードと統合-第-13–18-週" aria-label="Permalink to &quot;フェーズ 3 — スピードと統合（第 13–18 週）&quot;">​</a></h3><ul><li>単発の問題から、時間を計った読解・聴解のセットに移る。</li><li>読解では、筆者の主張、逆接の言葉、指示語の指す内容、各段落の役割に印を付ける。</li><li>聴解では、設問のタイプを予測し、答えを左右する情報だけを拾う。</li><li>60–90 秒の音声で週 3 回シャドーイングし、音の聞き取りとリズムを鍛える。</li><li>古い語彙を維持する。想起率が 85% を下回ったら新規カードを減らす。</li></ul><h3 id="フェーズ-4-—-試験への準備-第-19–23-週" tabindex="-1">フェーズ 4 — 試験への準備（第 19–23 週） <a class="header-anchor" href="#フェーズ-4-—-試験への準備-第-19–23-週" aria-label="Permalink to &quot;フェーズ 4 — 試験への準備（第 19–23 週）&quot;">​</a></h3><ul><li>週末ごとに、区分別テストと模擬試験全体を交互に行う。</li><li>本番の時間配分、休憩、音声の再生、解答用紙の扱いを再現する。</li><li>選択肢の誤答がなぜ誤りなのかを見直す。勘で当たった問題は特に念入りに。</li><li>平日は弱いサブスキルを 1 つずつ補強する。</li></ul><h3 id="フェーズ-5-—-調整-第-24-週" tabindex="-1">フェーズ 5 — 調整（第 24 週） <a class="header-anchor" href="#フェーズ-5-—-調整-第-24-週" aria-label="Permalink to &quot;フェーズ 5 — 調整（第 24 週）&quot;">​</a></h3><ul><li>混同しやすい文法のペア、間違えやすい漢字の読み、聴解の手がかり語を復習する。</li><li>疲れ切るフルテストは避け、短い時間制限つきセットにとどめる。</li><li>当日の段取りを確認し、睡眠を守る。</li></ul><h2 id="月-1-回の実践チェック" tabindex="-1">月 1 回の実践チェック <a class="header-anchor" href="#月-1-回の実践チェック" aria-label="Permalink to &quot;月 1 回の実践チェック&quot;">​</a></h2><p>4 週間に 1 回：</p><ul><li>記事を 1 本読み、2 分間で口頭要約する；</li><li>20 分の会話または言語交換をする；</li><li>短いビジネスメッセージを書き、添削してもらう；</li><li>試験勉強で伸びていること、伸びていないことを書き留める。</li></ul><h2 id="最初の-7-日間" tabindex="-1">最初の 7 日間 <a class="header-anchor" href="#最初の-7-日間" aria-label="Permalink to &quot;最初の 7 日間&quot;">​</a></h2><ul><li>[ ] 現状把握のサンプル問題を解き、区分別の得点を記録する。</li><li>[ ] スキルごとに中心となる教材を 1 つ選ぶ。</li><li>[ ] 復習デッキとミスノートを作る。</li><li>[ ] 信頼できる読解・聴解の素材を 3 つ保存する。</li><li>[ ] 最初の 90 分のミックス演習を予定に入れる。</li></ul>',23)])])}const p=t(r,[["render",d]]);export{b as __pageData,p as default};
